:root {
  --bg: #1e1e2e;
  --card: #2a2a3c;
  --text: #e0e0f0;
  --accent: #7aa2f7;
  --highlight: #f7c948;
  --bar: #5a5a7a;
  --bar-fill: #7aa2f7;
}

* { box-sizing: border-box; }

[hidden] { display: none !important; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: 16px;
  padding: 24px 20px;
  width: 100%;
  max-width: 520px;
  box-shadow: 0 8px 32px rgba(0,0,0,0.4);
}

h1 {
  margin: 0 0 4px;
  font-size: 1.5rem;
  text-align: center;
}

.subtitle {
  margin: 0 0 20px;
  text-align: center;
  opacity: 0.7;
  font-size: 0.95rem;
}

.inputs {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(64px, 1fr));
  gap: 8px;
  margin-bottom: 20px;
}

.inputs label {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 0.85rem;
  text-align: center;
}

.inputs input {
  width: 100%;
  padding: 8px 4px;
  font-size: 1rem;
  text-align: center;
  border: 2px solid transparent;
  border-radius: 8px;
  background: #1e1e2e;
  color: var(--text);
  outline: none;
  transition: border-color 0.15s, background 0.15s;
}

.inputs input:hover {
  background: #252538;
}

.inputs input:focus-visible {
  border-color: var(--accent);
  background: #252538;
}

.inputs input:active {
  background: #1a1a28;
}

.chart {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 6px;
  height: 180px;
  padding: 8px;
  margin-bottom: 20px;
  background: #1e1e2e;
  border-radius: 12px;
  image-rendering: pixelated;
}

.bar-wrap {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  height: 100%;
}

.bar {
  width: 100%;
  max-width: 36px;
  background: var(--bar);
  border-radius: 2px 2px 0 0;
  transition: height 0.2s ease, background 0.2s;
  position: relative;
}

.bar.longest {
  background: var(--highlight);
  box-shadow: 0 0 0 2px var(--highlight);
}

.bar-label {
  margin-top: 6px;
  font-size: 0.75rem;
  opacity: 0.7;
}

.stats {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 1rem;
}

.stats p { margin: 0; }

.stats strong { color: var(--accent); }

@media (max-width: 420px) {
  .inputs { grid-template-columns: repeat(4, 1fr); }
  .chart { height: 150px; gap: 4px; }
  .bar-label { font-size: 0.65rem; }
}

const DAYS = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'];
const LABELS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const MAX = 12;

const inputs = DAYS.map(id => document.getElementById(id));
const chart = document.getElementById('chart');
const averageEl = document.getElementById('average');
const longestEl = document.getElementById('longest');

function clamp(value) {
  if (isNaN(value)) return 0;
  return Math.min(MAX, Math.max(0, value));
}

function readValues() {
  return inputs.map(input => {
    let v = parseFloat(input.value);
    if (isNaN(v)) v = 0;
    v = clamp(v);
    input.value = v;
    return v;
  });
}

function render() {
  const values = readValues();
  const maxVal = Math.max(...values);
  const maxIndex = values.indexOf(maxVal);

  chart.innerHTML = '';
  values.forEach((v, i) => {
    const wrap = document.createElement('div');
    wrap.className = 'bar-wrap';

    const bar = document.createElement('div');
    bar.className = 'bar' + (v === maxVal && maxVal > 0 ? ' longest' : '');
    bar.style.height = (v / MAX * 100) + '%';
    bar.setAttribute('aria-label', LABELS[i] + ': ' + v + ' hours');

    const label = document.createElement('span');
    label.className = 'bar-label';
    label.textContent = LABELS[i];

    wrap.appendChild(bar);
    wrap.appendChild(label);
    chart.appendChild(wrap);
  });

  const sum = values.reduce((a, b) => a + b, 0);
  const avg = sum / values.length;
  averageEl.textContent = avg.toFixed(1);

  if (maxVal > 0) {
    longestEl.textContent = LABELS[maxIndex] + ' (' + maxVal + ' h)';
  } else {
    longestEl.textContent = '—';
  }
}

inputs.forEach(input => {
  input.addEventListener('input', render);
  input.addEventListener('change', render);
});

render();
